begin;
insert into public.domains (slug, name, intro, sort) values ('sites-performance-referencement', 'Sites web, performance et référencement', 'Un site lent, introuvable ou fragile fait perdre des clients chaque jour, sans que son propriétaire le voie.', 10) on conflict (slug) do update set name = excluded.name, intro = excluded.intro, sort = excluded.sort;
insert into public.domains (slug, name, intro, sort) values ('e-commerce-paiements', 'E-commerce et paiements', 'Chaque friction dans le parcours d''achat se paie en ventes perdues : paiement, stock, livraison, confiance.', 20) on conflict (slug) do update set name = excluded.name, intro = excluded.intro, sort = excluded.sort;
insert into public.domains (slug, name, intro, sort) values ('securite-conformite-fiabilite', 'Sécurité, conformité et fiabilité', 'Une intrusion, une amende ou une panne peut arrêter une activité en une journée. Nous travaillons de façon défensive et vérifiable.', 30) on conflict (slug) do update set name = excluded.name, intro = excluded.intro, sort = excluded.sort;
