insert into public.domains (slug, name, intro, sort) values ('contenu-video-design', 'Contenu, vidéo et design', 'Un contenu juste, cohérent et rapide à produire est la première chose que voit un client.', 50) on conflict (slug) do update set name = excluded.name, intro = excluded.intro, sort = excluded.sort;
insert into public.domains (slug, name, intro, sort) values ('automatisation-ia', 'Automatisation et IA', 'Automatiser utilement libère du temps, à condition de garder l''humain là où cela compte.', 60) on conflict (slug) do update set name = excluded.name, intro = excluded.intro, sort = excluded.sort;
insert into public.domains (slug, name, intro, sort) values ('donnees-finance-gestion', 'Données, finance et gestion', 'Décider sans chiffres fiables revient à naviguer sans carte. Les outils financiers sont des aides au calcul, pas des conseils.', 70) on conflict (slug) do update set name = excluded.name, intro = excluded.intro, sort = excluded.sort;
