insert into public.domains (slug, name, intro, sort) values ('multilingue-accessibilite', 'Multilingue, accessibilité et marchés émergents', 'Un bon produit web fonctionne avec une connexion fragile, dans plusieurs langues et pour tous les utilisateurs.', 100) on conflict (slug) do update set name = excluded.name, intro = excluded.intro, sort = excluded.sort;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('site-invisible-sur-google', (select id from public.domains where slug = 'sites-performance-referencement'), 'Votre site est en ligne, mais Google ne le montre à personne', 'Un site bien fait qui n''apparaît sur aucune recherche utile ne rapporte aucun contact.', 'Indépendants, commerces locaux, PME.', 'Vous cherchez votre propre activité sur Google et vous ne vous trouvez pas, ou très loin. Aucune demande n''arrive depuis la recherche.', 'Chaque semaine, des clients qui cherchent exactement ce que vous vendez choisissent un concurrent visible.', 'Titres et descriptions absents ou identiques d''une page à l''autre, pages bloquées par erreur aux robots, absence de plan de site, contenu trop mince et pages qui ne se renvoient pas les unes vers les autres.', 'Nous auditons l''indexation et la structure de chaque page, corrigeons les balises, hiérarchisons les titres, relions les contenus entre eux et ajoutons les données structurées que Google exploite. Nous vérifions ensuite dans la Search Console que les pages sont bien prises en compte.', array['Audit technique et sémantique priorisé par impact','Balises, titres et descriptions réécrits page par page','Plan de site et fichier robots corrects','Données structurées adaptées à votre activité','Suivi de l''indexation dans la Search Console']::text[], 'Des pages comprises et indexées par Google, avec un plan d''action clair pour gagner en visibilité durablement. Aucun classement n''est garanti : il dépend aussi de la concurrence.', array['Next.js','Search Console','JSON-LD','Node.js']::text[], array['entreprise']::text[], 'tool', 'seo', 'Saisissez l''adresse d''une page : l''outil lit son code public et liste ce qui l''empêche d''être bien comprise par Google.', 'published', true, 10, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('site-vulnerable-en-tetes-de-securite', (select id from public.domains where slug = 'securite-conformite-fiabilite'), 'Votre site laisse des portes ouvertes aux attaques courantes', 'La plupart des intrusions exploitent des protections de base que personne n''a activées.', 'Sites vitrines, boutiques, applications sur mesure.', 'Rien ne semble anormal, et pourtant le serveur n''envoie aucune des consignes de protection que les navigateurs attendent.', 'Un script malveillant injecté dans une page peut voler des données de vos visiteurs ou afficher de fausses pages de paiement à votre nom.', 'Requêtes construites par simple concaténation de texte, contenus non échappés à l''affichage, et absence de politique de sécurité du contenu et d''en-têtes de protection.', 'Nous mesurons l''exposition réelle, puis nous corrigeons à deux niveaux : le code (requêtes préparées, échappement, validation côté serveur) et la configuration (HSTS, CSP, protection contre l''intégration frauduleuse, politique de référent).', array['Rapport des protections présentes et manquantes','Configuration serveur prête à appliquer','Politique de sécurité du contenu adaptée à votre site','Correctifs de code pour les injections','Contrôle de non-régression avant mise en ligne']::text[], 'Un site qui respecte les protections standard des navigateurs, avec une preuve de contrôle que vous pouvez refaire à tout moment.', array['Node.js','HSTS','CSP','Next.js']::text[], array['entreprise']::text[], 'tool', 'headers', 'L''outil lit uniquement les en-têtes publics de votre site, sans le tester ni le perturber, puis note chaque protection.', 'published', true, 20, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('emails-qui-finissent-en-spam', (select id from public.domains where slug = 'securite-conformite-fiabilite'), 'Vos devis et vos factures arrivent en courrier indésirable', 'Un message envoyé mais jamais lu est une vente qui se perd en silence.', 'Boutiques, formateurs, prestataires qui envoient devis, factures et newsletters.', 'Des clients disent n''avoir « rien reçu ». Vos devis restent sans réponse, vos relances aussi.', 'Des devis jamais vus, des paiements retardés, et une adresse que les messageries finissent par juger suspecte.', 'Les enregistrements SPF, DKIM et DMARC de votre domaine sont absents, incomplets ou contradictoires : les messageries ne peuvent pas vérifier que c''est bien vous qui écrivez.', 'Nous authentifions entièrement votre domaine, nettoyons vos listes d''envoi, mettons en place une montée en volume progressive et un suivi des plaintes, avec un lien de désinscription visible.', array['Enregistrements SPF, DKIM et DMARC corrects','Plan de montée en volume pour un domaine récent','Nettoyage et segmentation de la liste d''envoi','Rapports DMARC lisibles']::text[], 'Des messages correctement authentifiés, donc éligibles à la boîte de réception. La délivrabilité dépend aussi de votre réputation d''expéditeur.', array['DNS','SPF','DKIM','DMARC']::text[], array['entreprise']::text[], 'tool', 'email-auth', 'Saisissez votre nom de domaine : l''outil interroge le DNS public et analyse vos enregistrements SPF et DMARC.', 'published', true, 30, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('paniers-abandonnes-avant-le-paiement', (select id from public.domains where slug = 'e-commerce-paiements'), 'Vos clients remplissent leur panier, puis disparaissent avant de payer', 'Le trafic est déjà payé : la perte se joue dans les dernières étapes.', 'Boutiques en ligne, vendeurs indépendants.', 'Vos visites sont correctes, mais la majorité des paniers n''aboutit pas à une commande.', 'Chaque panier abandonné est une vente que vous avez déjà payée en publicité ou en temps.', 'Frais de livraison révélés trop tard, création de compte obligatoire, formulaire trop long, moyens de paiement insuffisants, page de paiement lente.', 'Nous simplifions le parcours : achat sans compte, frais visibles dès le panier, saisie d''adresse assistée, paiement sur une page, et relance par e-mail des paniers laissés en route.', array['Analyse du parcours d''achat étape par étape','Tunnel de paiement simplifié','Intégration du paiement sécurisé','Séquence de relance des paniers abandonnés']::text[], 'Un parcours plus court et plus rassurant. L''outil ci-contre estime le potentiel avec vos propres chiffres ; il s''agit d''une simulation, pas d''une promesse.', array['Next.js','Stripe Checkout','E-mails transactionnels']::text[], array['entreprise']::text[], 'tool', 'cart', 'Renseignez votre trafic et votre taux de conversion : la simulation estime le chiffre d''affaires récupérable. Les valeurs de départ sont des exemples.', 'published', true, 40, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('budget-publicitaire-sans-mesure-de-rentabilite', (select id from public.domains where slug = 'marketing-acquisition'), 'Vous dépensez en publicité sans savoir si vous gagnez de l''argent', 'Des ventes arrivent, mais personne ne sait si l''opération est rentable.', 'Boutiques et prestataires qui lancent des annonces Meta ou Google.', 'Le budget part chaque jour. Il y a des ventes, sans certitude sur le résultat réel une fois tous les coûts payés.', 'On peut perdre de l''argent sur chaque vente en pensant en gagner, et couper les campagnes qui fonctionnent.', 'La marge par vente n''a jamais été calculée, les conversions ne sont pas suivies de bout en bout, et le ciblage est trop large.', 'Nous calculons d''abord votre marge réelle par vente, en déduisons le coût d''acquisition maximal et le seuil de rentabilité publicitaire, puis nous mettons en place le suivi des conversions pour piloter avec des chiffres fiables.', array['Modèle de marge par produit','Seuil de rentabilité publicitaire et coût d''acquisition maximal','Plan de marquage des conversions','Tableau de pilotage par canal']::text[], 'Une décision publicité fondée sur votre marge réelle. Le calculateur est un outil d''aide au calcul, pas un conseil financier.', array['Google Tag Manager','API de conversion','Tableur ou tableau de bord']::text[], array['entreprise']::text[], 'tool', 'roas', 'Saisissez prix, coûts, frais et taux de retour : vous obtenez la marge réelle par vente et le seuil à dépasser pour gagner de l''argent.', 'published', true, 50, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('test-ab-declare-gagnant-trop-tot', (select id from public.domains where slug = 'marketing-acquisition'), 'Votre test A/B a « gagné » après quarante visites, puis les résultats se sont dégradés', 'Arrêter un test dès qu''un écart apparaît donne presque toujours un faux gagnant.', 'Responsables de site, e-commerçants, équipes marketing.', 'Une variante semble nettement meilleure très vite. Vous la déployez, et les résultats retombent.', 'Des décisions de design et de prix prises sur du hasard, et du temps de développement gaspillé.', 'Échantillon trop petit, arrêt dès que l''écart paraît favorable, et aucune taille d''échantillon fixée avant de commencer.', 'Nous fixons avant le test l''écart minimal qui compte, calculons le nombre de visiteurs nécessaire, laissons le test courir sur des cycles complets de semaine et appliquons un seuil de confiance défini à l''avance.', array['Protocole de test écrit avant lancement','Calcul de la taille d''échantillon','Lecture des résultats en langage clair']::text[], 'Des décisions appuyées sur des résultats statistiquement solides, ou la certitude qu''il faut plus de données.', array['Statistiques','Outil de test A/B']::text[], array['entreprise']::text[], 'tool', 'abtest', 'Calculez combien de visiteurs il faut avant de lancer le test, puis vérifiez si un résultat observé est significatif.', 'published', false, 60, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('comptes-clients-pirates-par-mots-de-passe-voles', (select id from public.domains where slug = 'securite-conformite-fiabilite'), 'Des comptes clients sont piratés avec des mots de passe déjà volés ailleurs', 'Vos clients réutilisent leurs mots de passe : une fuite sur un autre site devient une intrusion chez vous.', 'Sites avec comptes clients, plateformes, applications web.', 'Des comptes sont pris sans que vos serveurs aient été attaqués : l''attaquant essaie simplement des identifiants déjà circulant.', 'Des clients qui perdent leurs données, un support submergé et une confiance difficile à reconstruire.', 'Mots de passe réutilisés, hachage faible, aucune double authentification et aucune limite aux tentatives de connexion.', 'Nous mettons en place un hachage moderne (Argon2id), la double authentification par code temporaire, la limitation des tentatives et le refus des mots de passe présents dans des fuites connues, sans jamais transmettre le mot de passe en clair.', array['Inscription et connexion durcies','Double authentification par application','Contrôle des mots de passe compromis','Limitation des tentatives et alertes']::text[], 'Une authentification qui résiste aux attaques par réutilisation d''identifiants.', array['Argon2id','TOTP','Have I Been Pwned (k-anonymat)','Supabase Auth']::text[], array['entreprise']::text[], 'tool', 'password-leak', 'Le mot de passe n''est jamais envoyé : votre navigateur n''émet que les 5 premiers caractères de son empreinte SHA-1, selon la méthode du k-anonymat.', 'published', true, 70, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('images-trop-lourdes-qui-ralentissent-le-site', (select id from public.domains where slug = 'sites-performance-referencement'), 'Vos photos de plusieurs mégaoctets font fuir les visiteurs', 'Les images sont la première cause de lenteur, et la plus simple à corriger.', 'Boutiques, blogueurs, photographes, tout site avec beaucoup d''images.', 'Les pages mettent des secondes à s''afficher, surtout sur téléphone avec un forfait limité.', 'Visiteurs qui repartent, classement Google pénalisé et forfaits de données consommés pour rien.', 'Images envoyées telles que sorties de l''appareil, dans des formats anciens et à des dimensions bien supérieures à l''affichage.', 'Nous redimensionnons à la taille réellement affichée, convertissons en WebP ou AVIF, ajustons la compression et servons plusieurs versions selon l''écran, avec chargement différé.', array['Chaîne de traitement automatique des images','Versions adaptées à chaque écran','Budget de poids par page']::text[], 'Des pages sensiblement plus légères, sans perte visible de qualité.', array['WebP','AVIF','Sharp','CDN']::text[], array['entreprise','particulier']::text[], 'tool', 'image-compress', 'Déposez vos images : elles sont compressées dans votre navigateur, sans être envoyées à un serveur. Comparez poids et qualité avant de télécharger.', 'published', false, 80, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('site-wordpress-pirate-redirections-et-spam', (select id from public.domains where slug = 'securite-conformite-fiabilite'), 'Votre site WordPress redirige vers des pages douteuses ou affiche du spam', 'Un site piraté se répare mieux et plus vite quand on suit un ordre précis.', 'Petites entreprises et blogueurs sur WordPress.', 'Le site redirige vers des pages étrangères, affiche des annonces que vous n''avez pas posées, ou Google l''indique comme dangereux.', 'Perte de confiance, disparition des résultats de recherche et risque pour vos visiteurs.', 'Extensions et thèmes non mis à jour, mots de passe faibles, droits de fichiers trop larges et éditeur de fichiers actif dans l''administration.', 'Nous isolons le site, restaurons une sauvegarde saine, comparons les fichiers aux sommes de contrôle officielles, mettons tout à jour, changeons tous les accès, activons la double authentification, désactivons l''éditeur de fichiers et réglons les droits.', array['Intervention d''urgence en étapes documentées','Nettoyage vérifié par comparaison aux fichiers d''origine','Durcissement de la configuration','Surveillance après intervention']::text[], 'Un site propre, durci et surveillé, avec la liste de ce qui a été corrigé.', array['WP-CLI','Sommes de contrôle officielles','Pare-feu applicatif']::text[], array['entreprise']::text[], 'study', null, '', 'published', true, 90, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('chatbot-qui-invente-des-prix-et-des-promesses', (select id from public.domains where slug = 'automatisation-ia'), 'Votre assistant en ligne répond avec assurance… des choses fausses', 'Un assistant qui invente un tarif ou un délai engage votre entreprise.', 'Entreprises qui veulent répondre à leurs clients à toute heure.', 'L''assistant annonce des prix inexistants, des délais impossibles ou répond hors sujet avec aplomb.', 'Des clients induits en erreur, des litiges et parfois une responsabilité juridique.', 'Un modèle de langage utilisé sans base documentaire, sans citation de source et sans transfert vers un humain.', 'Nous construisons un assistant qui ne répond qu''à partir de vos documents : découpage des contenus, recherche des passages pertinents, citation des sources, refus hors périmètre et passage de relais à une personne.', array['Base de connaissances structurée à partir de vos documents','Assistant limité à vos contenus, avec sources visibles','Règles de refus et de transfert à un humain','Jeu de questions de contrôle avant mise en ligne']::text[], 'Un assistant dont chaque réponse peut être vérifiée dans vos propres documents.', array['Recherche vectorielle (pgvector)','Supabase','API de modèle de langage côté serveur']::text[], array['entreprise']::text[], 'study', null, '', 'published', false, 100, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('rendez-vous-fixes-par-allers-retours-de-messages', (select id from public.domains where slug = 'services-rh-metiers'), 'Fixer un rendez-vous demande dix messages et provoque des doubles réservations', 'Chaque message échangé pour trouver un créneau est du temps qui ne se facture pas.', 'Cabinets, coachs, salons, artisans, consultants.', 'Beaucoup de messages pour un seul rendez-vous, des créneaux réservés deux fois et des absences non prévenues.', 'Du temps perdu, des clients mécontents et des créneaux vides.', 'Agenda géré à la main, disponibilités jamais calculées, fuseaux horaires mal gérés et aucun verrou au moment de réserver.', 'Nous calculons les créneaux à partir de vos règles de disponibilité, protégeons la réservation contre les doublons, envoyons une confirmation avec fichier calendrier et des rappels automatiques.', array['Module de réservation en ligne','Règles de disponibilité paramétrables','Confirmation et rappels automatiques','Fichier calendrier pour chaque rendez-vous']::text[], 'Des rendez-vous pris en autonomie par vos clients, sans doublon.', array['Next.js','PostgreSQL','Fuseaux horaires','E-mails transactionnels']::text[], array['entreprise','particulier']::text[], 'study', null, '', 'published', false, 110, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('ventes-dispersees-dans-plusieurs-exports', (select id from public.domains where slug = 'donnees-finance-gestion'), 'Pour savoir ce qui se vend vraiment, il faut assembler trois fichiers à la main', 'Quand chaque personne obtient un chiffre différent, plus personne ne décide.', 'Dirigeants de PME, responsables de boutique.', 'La question « qu''est-ce qui se vend ? » demande une demi-journée de copier-coller, et les réponses varient selon la personne.', 'Des décisions tardives, fondées sur des chiffres contestés.', 'Exports séparés, absence de modèle de données commun et indicateurs jamais définis une fois pour toutes.', 'Nous définissons vos indicateurs une seule fois, construisons un modèle de données propre et un tableau de bord filtrable par période, produit et canal.', array['Dictionnaire des indicateurs','Modèle de données consolidé','Tableau de bord filtrable','Import automatique de vos exports']::text[], 'Un chiffre unique, le même pour tous, mis à jour sans manipulation.', array['PostgreSQL','Supabase','Next.js','Graphiques']::text[], array['entreprise']::text[], 'study', null, '', 'published', false, 120, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('site-lent-visiteurs-qui-repartent', (select id from public.domains where slug = 'sites-performance-referencement'), 'Votre site met plus de quatre secondes à s''afficher sur mobile', 'Les visiteurs quittent avant d''avoir vu votre offre, et Google le remarque.', 'PME, boutiques en ligne, blogueurs.', 'Le site paraît lent sur téléphone, les visiteurs repartent vite et le classement baisse.', 'Des ventes perdues avant même la première lecture, et moins de visibilité.', 'Images non compressées, JavaScript bloquant, absence de cache et de réseau de diffusion, serveur lent à répondre.', 'Nous mesurons les indicateurs essentiels du web (affichage principal, réactivité, stabilité visuelle), puis corrigeons dans l''ordre d''impact : images, chargement différé, découpage du code, cache et diffusion.', array['Mesure avant et après sur appareils réels','Plan de correction priorisé','Mise en place du cache et de la diffusion','Budget de performance à tenir']::text[], 'Un site mesurablement plus rapide, avec les chiffres avant et après publiés dans le rapport.', array['Next.js','Cloudflare','Sharp','PageSpeed Insights']::text[], array['entreprise']::text[], 'study', null, '', 'published', false, 130, now())
on conflict (slug) do nothing;
insert into public.problems (slug, domain_id, title, hook, who, symptom, cost, cause, what_we_do, deliverables, outcome, stack, audiences, format, tool_key, tool_intro, status, featured, sort, published_at)
values ('client-qui-ne-sait-pas-par-ou-commencer', (select id from public.domains where slug = 'services-rh-metiers'), 'Vous avez un projet web mais vous ne savez pas par où commencer', 'Trop d''options et des devis impossibles à comparer paralysent beaucoup de projets.', 'Entrepreneurs, associations, dirigeants.', 'Vous hésitez entre plusieurs solutions et plusieurs prix, sans savoir ce dont vous avez vraiment besoin.', 'Un projet qui reste à l''état d''idée, ou une dépense dans la mauvaise direction.', 'Le besoin n''est pas encore formulé, les priorités ne sont pas classées et il n''existe pas de cahier des charges.', 'Nous menons un cadrage court : objectif, public, budget, délai et existant, puis nous produisons une feuille de route priorisée, les premières étapes et les risques à anticiper.', array['Atelier de cadrage','Feuille de route priorisée','Cahier des charges comparable entre prestataires','Estimation par étape']::text[], 'Un projet clair, découpé et chiffrable, que vous soyez ensuite accompagné par Assavendo ou non.', array['Cadrage','Priorisation','Cahier des charges']::text[], array['entreprise','particulier']::text[], 'study', null, '', 'published', true, 140, now())
