insert into public.problems (slug, domain_id, title, who, symptom, cause, what_we_do, stack, audiences, format, status, sort)
values ('site-illisible-sur-telephone', (select id from public.domains where slug = 'sites-performance-referencement'), 'Site illisible sur téléphone', 'Commerçants, restaurants, associations.', 'La majorité des visites vient du mobile ; texte minuscule, boutons trop proches, menu inutilisable : les conversions se perdent.', 'Mise en page à largeur fixe, balise viewport absente, zones tactiles inférieures à 44-48 px, images non responsives.', 'Approche mobile-first, grille fluide CSS Grid/Flexbox, unités relatives, srcset pour les images, cibles tactiles ≥ 48 px, tests sur appareils réels.', array['HTML5','CSS Grid','Tailwind CSS','Chrome DevTools']::text[], array['entreprise']::text[], 'study', 'draft', 1000)
