values ('site-vitrine-trop-cher-ou-trop-long-a-creer-pour-un-artisan', (select id from public.domains where slug = 'sites-performance-referencement'), 'Site vitrine trop cher ou trop long à créer pour un artisan', 'Artisans, coachs, petits prestataires sans budget d''agence.', 'Les modèles gratuits se ressemblent, n''expliquent pas l''activité et ne génèrent aucun contact ; une agence dépasse le budget.', 'Contenu générique, pas de structure orientée conversion (offre, preuve, appel à l''action), pas d''optimisation locale.', 'Questionnaire guidé (activité, services, ville, couleurs) qui produit la structure de la page, les textes et le code HTML exportable.', array['Next.js','API de modèle de langage côté serveur','gabarits Tailwind','export ZIP']::text[], array['entreprise']::text[], 'study', 'draft', 1002)
