values ('avis-negatif-laisse-sans-reponse', (select id from public.domains where slug = 'marketing-acquisition'), 'Avis négatif laissé sans réponse', 'Commerces, restaurants, hôtels, prestataires de services.', 'Un avis négatif sans réponse, ou une réponse agressive, fait fuir les prochains clients.', 'Aucune procédure de réponse, réponses improvisées sous le coup de l''émotion.', 'Schéma en 4 temps : remercier, reconnaître le problème, proposer une solution en privé, conclure brièvement ; délai de réponse fixé.', array['API de modèle de langage côté serveur','consignes de ton','contrôle de longueur']::text[], array['entreprise']::text[], 'study', 'draft', 1027)
