values ('blog-qui-publie-sans-jamais-attirer-de-visiteurs', (select id from public.domains where slug = 'marketing-acquisition'), 'Blog qui publie sans jamais attirer de visiteurs', 'Entreprises et créateurs qui écrivent des articles sans résultats.', 'Des dizaines d''articles publiés, presque aucun visiteur.', 'Sujets choisis sans vérifier la demande de recherche, articles qui se concurrencent sur la même requête, aucun maillage interne, aucune mise à jour.', 'Étude des intentions de recherche, regroupement des sujets en familles reliées, plan éditorial priorisé, mise à jour trimestrielle des articles qui montent.', array['Search Console','tableur','outil de suggestions de requêtes. Domaine E · Contenu','rédaction','vidéo et design Le contenu est la première chose que voit un client ; il doit être juste','rapide à produire et cohérent. Ces fiches montrent des chaînes de production fiables plutôt que des manipulations artisanales']::text[], array['entreprise']::text[], 'study', 'draft', 1030)
