values ('textes-web-generiques-qui-ne-convertissent-pas', (select id from public.domains where slug = 'contenu-video-design'), 'Textes web génériques qui ne convertissent pas', 'Entreprises et rédacteurs qui produisent des pages et des articles.', 'Des textes copiés ou interchangeables n''attirent ni lecteurs ni classement, et ne donnent pas envie d''acheter.', 'Aucun brief, intention de recherche ignorée, structure improvisée, aucun contrôle de similarité avant publication.', 'Brief de rédaction complet (cible, intention, plan de titres, questions à couvrir, liens internes), rédaction par un humain, relecture factuelle, contrôle de similarité.', array['API de modèle de langage côté serveur','sortie JSON structurée','export Markdown']::text[], array['entreprise']::text[], 'study', 'draft', 1031)
