values ('application-qui-ralentit-a-mesure-que-les-donnees-augmentent', (select id from public.domains where slug = 'donnees-finance-gestion'), 'Application qui ralentit à mesure que les données augmentent', 'Équipes qui maintiennent une application ou un site avec base de données.', 'Les pages qui chargeaient en une seconde en demandent dix quand la base grossit.', 'Index manquants, requêtes répétées dans une boucle (problème N+1), absence de pagination, aucune mise en cache.', 'Analyse des plans de requête ( EXPLAIN ), ajout d''index ciblés, regroupement des requêtes, pagination par curseur, cache des résultats coûteux.', array['PostgreSQL ou MySQL','EXPLAIN ANALYZE ','Redis']::text[], array['entreprise']::text[], 'study', 'draft', 1055)
