insert into public.problems (slug, domain_id, title, who, symptom, cause, what_we_do, stack, audiences, format, status, sort)
values ('aucune-idee-d-ou-part-l-argent-chaque-mois', (select id from public.domains where slug = 'donnees-finance-gestion'), 'Aucune idée d''où part l''argent chaque mois', 'Particuliers, étudiants, jeunes actifs.', 'Les dépenses dépassent les revenus en fin de mois, des abonnements oubliés continuent d''être prélevés.', 'Aucun suivi, aucune catégorie, aucun récapitulatif des prélèvements récurrents.', 'Classeur de budget mensuel avec revenus, dépenses fixes et variables, abonnements et épargne cible, formules et synthèse automatiques. Outil de suivi, pas conseil financier.', array['génération de fichier Excel avec formules (SheetJS ou ExcelJS)','formats de cellules. Domaine H · Éducation','formation et produits numériques Enseigner et vendre du savoir en ligne pose des problèmes de pédagogie','de livraison et de confiance. Ces fiches relient la compétence technique à l''expérience de l''apprenant et à la protection du créateur']::text[], array['particulier']::text[], 'study', 'draft', 1056)
