values ('fiches-de-vocabulaire-faites-a-la-main-mise-en-page-cassee', (select id from public.domains where slug = 'formation-produits-numeriques'), 'Fiches de vocabulaire faites à la main, mise en page cassée', 'Apprenants de langues, enseignants, auteurs de listes de mots.', 'Recopier mots, traductions et exemples dans un document est long ; les langues écrites de droite à gauche se mélangent et se désalignent.', 'Traitement de texte sans gestion du sens d''écriture, polices sans les signes nécessaires, aucun format d''échange pour les applications de révision.', 'Import d''un tableau (mot, traduction, exemple), mise en page automatique en cartes imprimables, prise en charge du sens d''écriture, export pour applications de cartes mémoire.', array['HTML et CSS avec dir et unicode-bidi ','polices libres','rendu PDF','export texte']::text[], array['particulier']::text[], 'study', 'draft', 1060)
