values ('page-de-vente-d-un-produit-numerique-qui-ne-vend-pas', (select id from public.domains where slug = 'formation-produits-numeriques'), 'Page de vente d''un produit numérique qui ne vend pas', 'Créateurs de guides, de cours, de modèles et de services.', 'Le produit est bon, la page est visitée, mais personne n''achète.', 'Promesse floue, aucun aperçu du contenu, prix non justifié, garantie et conditions absentes, appel à l''action noyé.', 'Promesse mesurable, extrait gratuit, comparaison honnête avec les alternatives, garantie claire, questions fréquentes, un seul bouton d''achat.', array['HTML','CSS','page rapide','outil de mesure des clics']::text[], array['entreprise']::text[], 'study', 'draft', 1063)
