values ('certificat-de-formation-facile-a-falsifier', (select id from public.domains where slug = 'formation-produits-numeriques'), 'Certificat de formation facile à falsifier', 'Organismes de formation, associations, organisateurs d''événements.', 'N''importe qui peut modifier un PDF de certificat ; les employeurs n''ont aucun moyen de vérifier.', 'Document sans identifiant unique, sans signature, sans page de vérification publique.', 'Identifiant unique par certificat, signature numérique de l''enregistrement, QR code vers une page de vérification publique indiquant le nom, la formation et la date.', array['Node.js','HMAC ou signature asymétrique','génération de QR code','PDF. Domaine I · Services','RH','administration et secteurs métiers Chaque métier a son quotidien fait de papiers','de messages dispersés et de tableurs fragiles. Ces fiches prouvent la capacité à comprendre un métier et à le transformer en outil simple. Les documents générés sont des modèles à valider','pas des conseils juridiques']::text[], array['entreprise']::text[], 'study', 'draft', 1066)
