values ('menu-et-formulaires-impossibles-a-utiliser-au-clavier', (select id from public.domains where slug = 'multilingue-accessibilite'), 'Menu et formulaires impossibles à utiliser au clavier', 'Utilisateurs de lecteurs d''écran, personnes ne pouvant pas utiliser une souris, mais aussi tout utilisateur pressé qui navigue au clavier.', 'Le focus disparaît, on ne peut pas ouvrir le menu, les fenêtres modales piègent le clavier.', 'Éléments div cliquables à la place de vrais boutons, style de focus supprimé, ordre de tabulation incohérent, usage excessif ou erroné d''ARIA.', 'HTML sémantique, focus visible, lien d''évitement, ARIA seulement quand le HTML ne suffit pas, gestion du focus dans les modales, test avec NVDA ou VoiceOver.', array['HTML sémantique','CSS :focus-visible ','NVDA','VoiceOver']::text[], array['particulier']::text[], 'study', 'draft', 1083)
